import { mapValue, transform, transformValue, } from "motion-dom";
import { onCleanup } from "solid-js";
export function useTransform(input, inputRangeOrTransformer, outputRange, options) {
    if (typeof input === "function") {
        const value = transformValue(input);
        onCleanup(() => value.destroy());
        return value;
    }
    let value;
    if (Array.isArray(input)) {
        const transformer = typeof inputRangeOrTransformer === "function"
            ? inputRangeOrTransformer
            : transform(inputRangeOrTransformer, outputRange, options);
        value = transformValue(() => transformer(input.map((item) => item.get())));
    }
    else if (typeof inputRangeOrTransformer === "function") {
        const transformer = inputRangeOrTransformer;
        value = transformValue(() => transformer(input.get()));
    }
    else {
        value = mapValue(input, inputRangeOrTransformer, outputRange, options);
    }
    onCleanup(() => value.destroy());
    return value;
}
